/bin/bash -c "python3 - <<'PY'
# Check the attachment rule in Algorithm 1 on two valid MDS events.
triggers = [('t1','MDS'), ('t2','MDS')]
gold = {('t1','x','BaseComponent'), ('t2','x','TriedComponent')}
links = {(t,x) for t,x,r in gold}
args = {(x,r) for t,x,r in gold}
allowed = {'MDS': {'BaseComponent','TriedComponent'}}
decoded = {(t,x,r) for x,r in args for t,et in triggers if (t,x) in links and r in allowed[et]}
print('Gold attachments:', sorted(gold))
print('Decoded from gold labels:', sorted(decoded))
print('Spurious attachments:', sorted(decoded-gold))
swapped = {('t1','x','TriedComponent'), ('t2','x','BaseComponent')}
print('Swapped assignments have identical links and nugget roles:', links == {(t,x) for t,x,r in swapped} and args == {(x,r) for t,x,r in swapped})
PY"
